using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Threading;using WinBoard;
class CaptureProbe {
 static CaptureRecording record;static Window w;static Application app;static int steps;static DispatcherTimer timer;static string output;static DateTime started;
 [STAThread]static void Main(){try{Directory.CreateDirectory("results");var prefs=new CapturePreferences{Fps=0,Folder=""};prefs.Normalize();if(prefs.Fps!=30||string.IsNullOrEmpty(prefs.Folder))throw new Exception("Preference migration");prefs.Save("results/prefs.json");if(CapturePreferences.Load("results/prefs.json").Fps!=30)throw new Exception("Preference roundtrip");uint modifiers,key;CaptureHotkeys.Parse("Ctrl+Shift+F9",out modifiers,out key);if(modifiers!=6||key!=120)throw new Exception("Hotkey parser");bool rejected=false;try{CaptureHotkeys.Parse("A",out modifiers,out key);}catch(ArgumentException){rejected=true;}if(!rejected)throw new Exception("Unsafe bare letter hotkey accepted");var r=CaptureDesktop.Selection(new System.Drawing.Point(90,80),new System.Drawing.Point(-5,-8),new System.Drawing.Rectangle(0,0,100,100));if(r.X!=0||r.Y!=0||r.Width!=90||r.Height!=80)throw new Exception("Selection bounds");
 app=new Application();w=new Window{Title="WinBoard Capture Test Pattern",Width=640,Height=400,Background=Brushes.DarkSlateBlue,Topmost=true,WindowStartupLocation=WindowStartupLocation.CenterScreen};var label=new TextBlock{Text="WinBoard capture test\nNo microphone / desktop recording\nMoving test pattern",Foreground=Brushes.White,FontSize=26,Margin=new Thickness(30)};w.Content=label;
 w.Loaded+=(s,e)=>{started=DateTime.Now;timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=(a,b)=>{try{steps++;label.Text="WinBoard test frame "+steps+"\nCapture / Pause / Resume / Stop";if(steps==1){var target=CaptureDesktop.Targets().FirstOrDefault(t=>t.Handle==new WindowInteropHelper(w).Handle); // Own windows excluded from picker; construct explicit test source.
 target=new CaptureTarget{Handle=new WindowInteropHelper(w).Handle,Name="Test"};using(var bitmap=CaptureDesktop.CaptureWindow(target)){Board.SaveScreenshot(CaptureDesktop.ToSource(bitmap),"results/screenshot.png");}
 output=Path.GetFullPath("results/window.mp4");if(File.Exists(output))File.Delete(output);record=new CaptureRecording();record.Completed+=(path,error)=>app.Dispatcher.BeginInvoke(new Action(()=>{if(error!=null){Fail(error);return;}File.AppendAllText("results/pass.txt","PASS: PNG and native window H264 MP4; pause/resume/stop; no microphone capture\n");record.Dispose();app.Shutdown();}));record.Start(target,new CapturePreferences{SystemAudio=false,Microphone=false,Cursor=true,Fps=30},output);}
 if(steps==4){record.Pause();if(!record.Paused)throw new Exception("Pause failed");}if(steps==6){record.Resume();if(record.Paused)throw new Exception("Resume failed");}if(steps==9){record.Stop();if(!record.Finishing)throw new Exception("Stop failed");}if(steps>25)Fail("Recording completion timeout");}catch(Exception ex){Fail(ex.ToString());}};timer.Start();};app.Run(w);
 }catch(Exception ex){File.WriteAllText("error.txt",ex.ToString());Environment.ExitCode=1;}}
 static void Fail(string error){File.WriteAllText("error.txt",error);if(record!=null)record.Dispose();app.Shutdown(1);}
}
